import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { FinanceService, VenteService } from '../../core/services/api.service';

@Component({
  selector: 'app-caisses',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="page-container">
      <div class="page-header">
        <div>
          <h3>🏦 Gestion de Caisse</h3>
          <p class="subtitle">Suivi des flux de trésorerie</p>
        </div>
        <button class="btn btn-primary" (click)="load()">🔄 Actualiser</button>
      </div>

      <!-- Résumé global -->
      <div class="summary-section">
        <div class="summary-card total">
          <div class="summary-icon">💰</div>
          <div class="summary-content">
            <span class="summary-label">Total Disponible</span>
            <span class="summary-value">{{ getTotalGeneral() | number:'1.0-0' }} FCA</span>
          </div>
        </div>

        <div class="summary-card especes">
          <div class="summary-icon">💵</div>
          <div class="summary-content">
            <span class="summary-label">Espèces</span>
            <span class="summary-value">{{ getTotalEspaces() | number:'1.0-0' }} FCA</span>
          </div>
        </div>

        <div class="summary-card orange">
          <div class="summary-icon">📱</div>
          <div class="summary-content">
            <span class="summary-label">Orange Money</span>
            <span class="summary-value">{{ getTotalOM() | number:'1.0-0' }} FCA</span>
          </div>
        </div>

        <div class="summary-card wave">
          <div class="summary-icon">🌊</div>
          <div class="summary-content">
            <span class="summary-label">Wave</span>
            <span class="summary-value">{{ getTotalWave() | number:'1.0-0' }} FCA</span>
          </div>
        </div>

        <div class="summary-card carte">
          <div class="summary-icon">💳</div>
          <div class="summary-content">
            <span class="summary-label">Carte</span>
            <span class="summary-value">{{ getTotalCarte() | number:'1.0-0' }} FCA</span>
          </div>
        </div>
      </div>

      <!-- Stats rapides -->
      <div class="quick-stats">
        <div class="quick-stat" [class.active]="showWhat === 'paye'" (click)="showWhat = 'paye'">
          <span class="qs-value text-success">{{ ventesPayees.length }}</span>
          <span class="qs-label">Payées</span>
        </div>
        <div class="quick-stat" [class.active]="showWhat === 'credit'" (click)="showWhat = 'credit'">
          <span class="qs-value text-danger">{{ ventesCredits.length }}</span>
          <span class="qs-label">Crédits</span>
        </div>
        <div class="quick-stat" [class.active]="showWhat === 'partiel'" (click)="showWhat = 'partiel'">
          <span class="qs-value text-warning">{{ ventesPartiels.length }}</span>
          <span class="qs-label">Partiels</span>
        </div>
        <div class="quick-stat">
          <span class="qs-value">{{ totalVentes }}</span>
          <span class="qs-label">Total Ventes</span>
        </div>
      </div>

      <!-- Par Caisse -->
      <div class="caisses-section">
        <h4>📊 Soldes par Caisse</h4>
        <div class="caisses-mini-grid">
          <div class="caisse-mini-card" *ngFor="let c of caisses" (click)="voirHistorique(c)">
            <div class="caisse-mini-header">
              <strong>{{ c.nom }}</strong>
              <small>{{ c.stock_nom }}</small>
            </div>
            <div class="caisse-mini-total">
              {{ c.solde || 0 | number:'1.0-0' }} FCA
            </div>
            <div class="caisse-mini-details">
              <span>💵 {{ c.solde_especes || 0 | number:'1.0-0' }}</span>
              <span>📱 {{ c.solde_orange_money || 0 | number:'1.0-0' }}</span>
            </div>
          </div>
        </div>
      </div>

      <!-- Ventes par statut -->
      <div class="ventes-section">
        <div class="section-header">
          <h4>
            <span *ngIf="showWhat === 'paye'">✅</span>
            <span *ngIf="showWhat === 'credit'">❌</span>
            <span *ngIf="showWhat === 'partiel'">💰</span>
            {{ getVentesLabel() }}
          </h4>
          <span class="section-total">{{ getVentesTotal() | number:'1.0-0' }} FCA</span>
        </div>

        <div class="ventes-table-container">
          <table class="ventes-table">
            <thead>
              <tr>
                <th>N°</th>
                <th>Client</th>
                <th>Montant</th>
                <th *ngIf="showWhat !== 'credit'">Payé</th>
                <th *ngIf="showWhat === 'credit' || showWhat === 'partiel'">Reste</th>
                <th>Date</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              <tr *ngFor="let v of getCurrentVentes()">
                <td>{{ v.numero }}</td>
                <td>{{ v.client_nom }}</td>
                <td>{{ v.montant_total | number:'1.0-0' }} FCA</td>
                <td *ngIf="showWhat !== 'credit'" class="text-success">{{ v.montant_paye | number:'1.0-0' }} FCA</td>
                <td *ngIf="showWhat === 'credit' || showWhat === 'partiel'" class="text-danger">{{ v.montant_restant | number:'1.0-0' }} FCA</td>
                <td>{{ v.date_vente | date:'dd/MM/yyyy' }}</td>
                <td>
                  <button class="btn-action" (click)="enregistrerPaiement(v)" *ngIf="v.montant_restant > 0">
                    💳 Payer
                  </button>
                </td>
              </tr>
              <tr *ngIf="getCurrentVentes().length === 0">
                <td [attr.colspan]="showWhat === 'credit' ? 7 : 7" class="text-center text-muted">
                  Aucune vente
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      <!-- Actions rapides -->
      <div class="actions-bar">
        <button class="btn-action-large" (click)="openAjust('entree')">
          <span>➕</span> Entrée Caisse
        </button>
        <button class="btn-action-large danger" (click)="openAjust('sortie')">
          <span>➖</span> Sortie Caisse
        </button>
        <button class="btn-action-large info" (click)="loadMouvements()">
          <span>📋</span> Historique
        </button>
      </div>

      <!-- Historique récents -->
      <div class="mouvements-section" *ngIf="mouvements.length > 0">
        <h4>🕐 Derniers Mouvementements</h4>
        <div class="mouvements-list">
          <div class="mouvement-item" *ngFor="let m of mouvements.slice(0, 10)" 
               [class.entree]="m.type === 'entree'" 
               [class.sortie]="m.type === 'sortie'">
            <span class="mvt-icon">{{ m.type === 'entree' ? '⬆️' : '⬇️' }}</span>
            <div class="mvt-content">
              <span class="mvt-desc">{{ m.description }}</span>
              <span class="mvt-date">{{ m.date_mouvement | date:'dd/MM HH:mm' }}</span>
            </div>
            <span class="mvt-montant" [class.text-success]="m.type === 'entree'" [class.text-danger]="m.type === 'sortie'">
              {{ m.type === 'entree' ? '+' : '-' }}{{ m.montant | number:'1.0-0' }} FCA
            </span>
          </div>
        </div>
      </div>

      <!-- Paiement Modal -->
      <div class="modal-overlay" *ngIf="showPaiement" (click)="showPaiement=false">
        <div class="modal-card" (click)="$event.stopPropagation()">
          <div class="modal-header">
            <h4>💳 Enregistrer Paiement</h4>
            <button class="close-btn" (click)="showPaiement=false">✕</button>
      </div>

      <!-- Paiement Modal -->
      <div class="modal-overlay" *ngIf="showPaiement" (click)="showPaiement=false">
        <div class="modal-card" style="max-width:400px" (click)="$event.stopPropagation()">
          <div class="modal-header">
            <h4>💳 Enregistrer Paiement</h4>
            <button class="close-btn" (click)="showPaiement=false">✕</button>
          </div>
          <div class="modal-form" *ngIf="selectedVente">
            <div class="vente-info-box">
              <p><strong>Vente:</strong> {{ selectedVente.numero }}</p>
              <p><strong>Client:</strong> {{ selectedVente.client_nom }}</p>
              <p><strong>Total:</strong> {{ selectedVente.montant_total | number:'1.0-0' }} FCA</p>
              <p><strong>Déjà payé:</strong> {{ selectedVente.montant_paye | number:'1.0-0' }} FCA</p>
              <p><strong>Restant dû:</strong> <span style="color:red">{{ selectedVente.montant_restant | number:'1.0-0' }} FCA</span></p>
            </div>
            <div class="form-group">
              <label>Montant à payer (FCFA)</label>
              <input type="number" [(ngModel)]="paiementMontant" [max]="selectedVente.montant_restant" min="0" />
            </div>
            <div class="form-group">
              <label>Mode de Paiement</label>
              <select [(ngModel)]="paiementMode">
                <option value="espece">Espèce</option>
                <option value="orange_money">Orange Money</option>
                <option value="wave">Wave</option>
                <option value="carte">Carte Bancaire</option>
              </select>
            </div>
            <div class="modal-footer">
              <button class="btn btn-secondary" (click)="showPaiement=false">Annuler</button>
              <button class="btn btn-success" (click)="confirmPaiement()">✓ Valider</button>
            </div>
          </div>
        </div>
      </div>

      <!-- Ajustement Modal -->
      <div class="modal-overlay" *ngIf="showAjust" (click)="showAjust=false">
        <div class="modal-card" style="max-width:400px" (click)="$event.stopPropagation()">
          <div class="modal-header">
            <h4>{{ ajustType === 'entree' ? '+ Entrée Caisse' : '- Sortie Caisse' }}</h4>
            <button class="close-btn" (click)="showAjust=false">✕</button>
          </div>
          <div class="modal-form">
            <div class="form-group">
              <label>Montant (FCFA) *</label>
              <input type="number" [(ngModel)]="ajustMontant" min="1" />
            </div>
            <div class="form-group">
              <label>Mode de paiement</label>
              <select [(ngModel)]="ajustMode">
                <option value="espece">Espèces</option>
                <option value="orange_money">Orange Money</option>
                <option value="wave">Wave</option>
                <option value="carte">Carte</option>
              </select>
            </div>
            <div class="form-group">
              <label>Description</label>
              <input type="text" [(ngModel)]="ajustDescription" placeholder="Motif..." />
            </div>
            <div class="modal-footer">
              <button class="btn btn-secondary" (click)="showAjust=false">Annuler</button>
              <button class="btn btn-primary" (click)="confirmAjust()">Valider</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .stats-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin-bottom: 24px; }
    .stat-card { background: white; border-radius: 12px; padding: 16px 20px; border-left: 4px solid; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
    .stat-card.green { border-color: #10b981; }
    .stat-card.blue { border-color: #3b82f6; }
    .stat-card.red { border-color: #ef4444; }
    .stat-card strong { display: block; font-size: 20px; font-weight: 800; }
    .stat-card small { color: #999; font-size: 12px; }
    .soldes-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; margin-bottom: 24px; }
    .solde-card { background: white; border-radius: 14px; padding: 20px; border: 1px solid #f0f0f0; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
    .solde-header { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }
    .solde-icon { font-size: 24px; }
    .solde-header strong { display: block; font-size: 14px; }
    .solde-header small { color: #999; font-size: 12px; }
    .solde-actions { display: flex; gap: 8px; margin-top: 12px; flex-wrap: wrap; }
    .soldes-details { background: #f9fafb; border-radius: 8px; padding: 12px; }
    .solde-row { display: flex; justify-content: space-between; padding: 4px 0; }
    .solde-row.total { border-top: 1px solid #e5e7eb; margin-top: 8px; padding-top: 8px; font-weight: 600; }
    .solde-label { color: #6b7280; font-size: 13px; }
    .solde-value { font-weight: 600; font-size: 13px; }
    .solde-value.om { color: #f59e0b; }
    .solde-value.wave { color: #6366f1; }
    .solde-value.carte { color: #10b981; }
    .card { background: white; border-radius: 14px; padding: 20px; margin-top: 20px; }
    .card-header { margin-bottom: 16px; }
    .card-header h4 { margin: 0; font-size: 15px; }
    .table { width: 100%; border-collapse: collapse; }
    .table th, .table td { padding: 12px; text-align: left; border-bottom: 1px solid #e5e7eb; }
    .table th { background: #f9fafb; font-weight: 600; font-size: 12px; }
    .text-center { text-align: center; }
    .text-danger { color: #dc2626; }
    .text-success { color: #16a34a; }
    .badge { padding: 3px 8px; border-radius: 12px; font-size: 11px; font-weight: 600; }
    .badge-success { background: #dcfce7; color: #16a34a; }
    .badge-danger { background: #fee2e2; color: #dc2626; }
    .modal-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); display: flex; align-items: center; justify-content: center; z-index: 1000; }
    .modal-card { background: white; border-radius: 14px; padding: 24px; max-width: 500px; width: 90%; }
    .modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }
    .modal-header h4 { margin: 0; }
    .close-btn { background: none; border: none; font-size: 20px; cursor: pointer; }
    .form-group { margin-bottom: 16px; }
    .form-group label { display: block; margin-bottom: 6px; font-weight: 500; }
    .form-group input, .form-group select { width: 100%; padding: 10px; border: 1px solid #e5e7eb; border-radius: 8px; }
    .modal-footer { display: flex; gap: 12px; justify-content: flex-end; margin-top: 20px; }
    .btn { padding: 10px 16px; border-radius: 8px; border: none; cursor: pointer; font-weight: 500; }
    .btn-sm { padding: 6px 12px; font-size: 13px; }
    .btn-primary { background: #ff6b00; color: white; }
    .btn-secondary { background: #e5e7eb; }
    .btn-success { background: #10b981; color: white; }
    .btn-danger { background: #dc2626; color: white; }
    .btn-info { background: #3b82f6; color: white; }
    .vente-info-box { background: #f8f9fa; border-radius: 10px; padding: 14px; margin-bottom: 16px; }
    .vente-info-box p { margin: 4px 0; font-size: 13px; }
  `]
})
export class CaissesComponent implements OnInit, OnDestroy {
  caisses: any[] = [];
  mouvements: any[] = [];
  loading = false;

  // Auto-refresh
  private refreshInterval: any;
  private routeSubscription: any;

  // Ventes
  ventesPayees: any[] = [];
  ventesCredits: any[] = [];
  ventesPartiels: any[] = [];
  totalPaye = 0;
  totalCredit = 0;
  totalVentes = 0;
  showWhat = 'paye';

  // Modals
  showAjust = false;
  showPaiement = false;
  ajustType = 'entree';
  ajustMontant = 0;
  ajustMode = 'espece';
  ajustDescription = '';
  selectedCaisse: any = null;

  // Paiement
  selectedVente: any = null;
  paiementMontant = 0;
  paiementMode = 'espece';

  constructor(
    private financeService: FinanceService,
    private venteService: VenteService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.load();

    // Auto-refresh every 30 seconds
    this.refreshInterval = setInterval(() => {
      this.load();
    }, 30000);

    // Refresh when returning to caisses from other pages
    this.routeSubscription = this.router.events.pipe(
      filter(event => event instanceof NavigationEnd)
    ).subscribe(() => {
      if (window.location.pathname.includes('caisses')) {
        this.load();
      }
    });
  }

  ngOnDestroy(): void {
    if (this.refreshInterval) {
      clearInterval(this.refreshInterval);
    }
    if (this.routeSubscription) {
      this.routeSubscription.unsubscribe();
    }
  }

  load(): void {
    this.loading = true;
    this.financeService.caisses().subscribe({
      next: d => { this.caisses = d.results || d; this.loading = false; },
      error: () => { this.loading = false; }
    });

    // Charger tous les mouvements de toutes les caisses
    this.financeService.mouvements({ page_size: 100, ordering: '-date_mouvement' }).subscribe({
      next: d => { this.mouvements = d.results || d; },
      error: () => { this.mouvements = []; }
    });

    this.loadVentes();
  }

  loadVentes(): void {
    this.venteService.list({ page_size: 500 }).subscribe({
      next: (d: any) => {
        const ventes = d.results || [];
        this.ventesPayees = ventes.filter((v: any) => v.statut === 'paye');
        this.ventesCredits = ventes.filter((v: any) => v.statut === 'credit');
        this.ventesPartiels = ventes.filter((v: any) => v.statut === 'partiel');
        this.totalPaye = this.ventesPayees.reduce((sum: number, v: any) => sum + (parseFloat(v.montant_paye) || 0), 0);
        this.totalCredit = this.ventesCredits.reduce((sum: number, v: any) => sum + (parseFloat(v.montant_restant) || 0), 0);
        this.totalVentes = ventes.length;
      },
      error: () => {}
    });
  }

  getTotalPaye(): number {
    return this.ventesPayees.reduce((sum: number, v: any) => sum + (parseFloat(v.montant_paye) || 0), 0);
  }

  getTotalCredit(): number {
    return this.ventesCredits.reduce((sum: number, v: any) => sum + (parseFloat(v.montant_restant) || 0), 0);
  }

  getModeLabel(mode: string): string {
    const modes: any = { 'espece': 'Espèce', 'orange_money': 'Orange Money', 'wave': 'Wave', 'carte': 'Carte', 'mixte': 'Mixte' };
    return modes[mode] || mode;
  }

  ajuster(caisse: any, type: string): void {
    this.selectedCaisse = caisse;
    this.ajustType = type;
    this.ajustMontant = 0;
    this.ajustMode = 'espece';
    this.ajustDescription = '';
    this.showAjust = true;
  }

  voirHistorique(caisse: any): void {
    this.selectedCaisse = caisse;
    this.financeService.historiqueCaisse(caisse.id).subscribe({
      next: (data: any) => { this.mouvements = data; },
      error: () => { this.mouvements = []; }
    });
  }

  confirmAjust(): void {
    if (!this.ajustMontant || !this.selectedCaisse) return;
    this.financeService.ajusterCaisse(this.selectedCaisse.id, {
      montant: this.ajustMontant,
      type: this.ajustType,
      mode_paiement: this.ajustMode,
      description: this.ajustDescription
    }).subscribe(updated => {
      const idx = this.caisses.findIndex(c => c.id === updated.id);
      if (idx >= 0) this.caisses[idx] = updated;
      this.showAjust = false;
      this.load();
    });
  }

  enregistrerPaiement(vente: any): void {
    this.selectedVente = vente;
    this.paiementMontant = vente.montant_restant;
    this.paiementMode = 'espece';
    this.showPaiement = true;
  }

  confirmPaiement(): void {
    if (!this.selectedVente || this.paiementMontant <= 0) return;
    this.venteService.payer(this.selectedVente.id, { 
      montant: this.paiementMontant, 
      mode_paiement: this.paiementMode 
    }).subscribe({
      next: () => {
        this.showPaiement = false;
        this.selectedVente = null;
        this.load();
      },
      error: (err) => {
        console.error(err);
        alert('Erreur lors du paiement');
      }
    });
  }
}
